// TRT: extract the required order photo (modele_image, base64) from the WhatsApp
// Flow response and output it as a binary file named 'data' for Google Drive.
// If there is no photo (e.g. an old order, or the flow field isn't published yet),
// photo_found=false and NO binary is produced — the IF node then skips the upload.
const body = $input.first().json;
const raw = body.modele_image ?? body.data?.modele_image ?? body.response?.modele_image ?? body;

function findPhoto(v) {
  if (!v) return null;
  if (Array.isArray(v)) { for (const x of v) { const r = findPhoto(x); if (r) return r; } return null; }
  if (typeof v === 'object') {
    const b64 = v.base64 || v.data || v.file || v.content || v.image;
    const name = v.file_name || v.filename || v.name || 'modele.jpg';
    const mime = v.mime_type || v.mimeType || v.type || 'image/jpeg';
    if (typeof b64 === 'string' && b64.length > 100) return { b64, name, mime };
    for (const k in v) { const r = findPhoto(v[k]); if (r) return r; }
    return null;
  }
  if (typeof v === 'string' && v.length > 100 && /^data:|^[A-Za-z0-9+/=\r\n]+$/.test(v)) return { b64: v, name: 'modele.jpg', mime: 'image/jpeg' };
  return null;
}

const p = findPhoto(raw);
if (!p) {
  return [{ json: { ...body, photo_found: false, photo_public_url: '' } }];
}
const clean = p.b64.replace(/^data:[^;]+;base64,/, '');
const fname = `${(body.nom || 'client').toString().replace(/[^\w-]+/g, '_')}_${(body.telephone || Date.now())}.jpg`;
return [{
  json: { ...body, photo_found: true, photo_file_name: fname, photo_mime: p.mime },
  binary: { data: { data: clean, mimeType: p.mime, fileName: fname } }
}];

// Carry the public Drive link forward for the Sheet/email.
// photo_public_url  -> DIRECT image URL that renders in <img> and Sheets =IMAGE()
// photo_drive_link  -> normal clickable Drive page
const up = $items('Upload to Drive')[0]?.json || {};
const order = $items('Extract photo (base64)')[0]?.json || {};
const id = up.id || '';
const direct = id ? `https://drive.google.com/thumbnail?id=${id}&sz=w1000` : '';
const page = up.webViewLink || (id ? `https://drive.google.com/file/d/${id}/view` : '');
return [{ json: { ...order, photo_public_url: direct, photo_drive_link: page } }];
